// Упражнения в тетрадь главы «Приставки». n — постоянный номер: не менять и не переиспользовать.
// Пропуск — «..» или варианты в скобках. В заданиях только бесспорные написания; спорное — только в «Тонкостях» теории.
// Цитаты сверены с корпусом классики (tools/lit); буква ё восстановлена.
const PS_CLASSIC=[
// ── Урок 1. Приставка. Приставки, которые не меняются
 {n:1,l:1,st:1,task:'Прочитать слова. Выписать только слова с приставкой, обозначить приставку и рядом записать однокоренное слово без приставки (или с другой приставкой). Слова без приставки записать отдельной строкой.',
  obr:'Подписать — писать (приставка под-). Здание — приставки нет.',
  body:'Подписать, здание, сдача, отбежать, звонок, обход, вход, надпись, здоровье, сгореть, змея, отдать, подарок, сделать, зверь, обложка, предсказание, звезда, вставка, сбор, здешний, оттенок, злой, сшить.',
  key:'С приставкой: под-писать (писать), с-дача (дать), от-бежать (бежать), об-ход (ходить), в-ход (выход), над-пись (запись), с-гореть (гореть), от-дать (дать), по-дарок (дар), с-делать (делать), об-ложка (положить), пред-сказание (сказать), в-ставка (поставить), с-бор (собирать), от-тенок (тень), с-шить (шить).<br>Без приставки: здание, звонок, здоровье, змея, зверь, звезда, здешний, злой — з и зд здесь начало корня.'},
 {n:2,l:1,st:2,task:'Списать словосочетания, выбирая букву из скобок. Обозначить приставку. В скобках записать слово с той же приставкой, где её согласный звучит ясно.',
  obr:'По(д/т)кова для коня — подкова (поднять).',
  body:'По(д/т)кова для коня, о(т/д)бить мяч, на(д/т)пись на стене, о(б/п)суждение книги, пре(д/т)ставление в театре, о(т/д)гадка к загадке, по(д/т)ход к реке, на(д/т)кусить яблоко, о(б/п)шить край платка, о(т/д)жать бельё, по(д/т)жечь сухие ветки, далёкий о(т/д)звук, радостное пре(д/т)чувствие, (в/ф)толкнуть лодку в воду, по(д/т)сказка учителя, о(т/д)дых на даче, о(б/п)хватить ствол руками, по(д/т)ставка для цветов.',
  key:'Подкова, отбить, надпись, обсуждение, представление, отгадка, подход, надкусить, обшить, отжать, поджечь, отзвук, предчувствие, втолкнуть, подсказка, отдых, обхватить, подставка. Ясно звучит: под- (поднять), от- (отнять), над- (надломить), об- (обнять), пред- (предложить), в- (внести).'},
 {n:3,l:1,st:2,task:'Вставить с или з. Объяснить: это приставка с- или начало корня? Для приставки записать слово без неё.',
  obr:'..лепить снеговика — слепить (лепить): приставка с-. ..мей — змей: з — начало корня.',
  body:'..делать уроки, ..дание вокзала, ..бить сосульку, крепкий ..доровый сон, ..гореть на солнце, ..жечь сухие листья, мы ..десь, ..дача экзамена, ..вонкий голос, ..шить платье, ..годиться в походе, ..дешние места, ..вери в лесу, ..дуть пылинку, ..жалиться над котёнком, острое ..рение, ..давить лимон, ..двинуть шкаф, ..дравствуй, ..жать кулак.',
  key:'Приставка с-: сделать (делать), сбить (бить), сгореть (гореть), сжечь (жечь), сдача (дать), сшить (шить), сгодиться (годиться), сдуть (дуть), сжалиться (жалость), сдавить (давить), сдвинуть (двинуть), сжать (жать).<br>З в корне: здание, здоровый, здесь, звонкий, здешние, звери, зрение, здравствуй.'},
 {n:4,l:1,st:3,task:'Вставить, где нужно, пропущенную букву: одну или две одинаковые согласные. Объяснить написание, разделив слово на приставку и корень. Осторожно: в нескольких словах нужна одна буква.',
  obr:'В..ести новое правило — ввести: в- + вести, две в.',
  body:'Лёд на реке начал о..аять. Нужно по..ержать друга в трудную минуту. На выставке стояла глиняная по..елка. Эксперт сразу заметил по..елку подписи. Мы купили по..ержанный велосипед. Брат о..олкнул лодку от берега. Слушатели согласно по..акивали. Тучи пришли о..уда, с запада. Чтобы открыть дверь, надо на..авить на кнопку. Через этот порт в..озят много машин. Рабочие с..ыпали зерно в мешки. Мама с..адила малыша с качелей.',
  key:'Оттаять (от-таять), поддержать (под-держать), поделка (по-делка, изделие), подделку (под-делка, фальшивка), подержанный (по-держать, бывший в употреблении), оттолкнул (от-толкнуть), поддакивали (под-дакать), оттуда (от-туда), надавить (на-давить — приставка на-, одна д), ввозят (в-возить), ссыпали (с-сыпать), ссадила (с-садить).'},
 {n:5,l:1,st:3,task:'Записать слова в два столбика: 1) согласный на конце приставки звучит так, как пишется; 2) звучит иначе (оглушается или озвончается). Обозначить приставку, во втором столбике надписать над ней звук, который слышится.',
  obr:'Поднять — в первый столбик. Подход — во второй: под- звучит как [пат].',
  body:'Подход, поднять, отдать, отнять, обсудить, обнять, вход, внести, сбить, снять, сделать, сшить, надпись, надломить, предсказать, предложить, отгадать, отломить, сжечь, слепить, подбежать, подкрасить, втащить, влететь.',
  key:'1) Поднять, отнять, обнять, внести, снять, надломить, предложить, отломить, слепить, подбежать (д перед звонким б), влететь.<br>2) Подход [т], отдать [д], обсудить [п], вход [ф], сбить [з], сделать [з], сшить [ш], надпись [т], предсказать [т], отгадать [д], сжечь [ж], подкрасить [т], втащить [ф].'},
 {n:6,l:1,st:4,task:'Найти в тексте ошибки в приставках и в начале слов (их восемь). Записать исправленный текст. Объяснить каждое исправление: какая приставка или почему здесь корень. Одно слово написано с ошибкой, хотя в нём вообще нет приставки.',
  obr:'Зделали → сделали: приставка с-, приставки «з-» нет.',
  body:'Вчера мы с братом зделали скворечник. Папа потсказал, как правильно атмерить и атпилить доски. Я крепко подерживал лестницу, пока брат прибивал домик к стволу берёзы. Потом мы збегали за мамой. Она фсмотрелась в нашу работу и похвалила нас. Теперь сдесь, у окна, мы будем каждый день наблюдать за птицами.',
  key:'Зделали → сделали (приставка с-); потсказал → подсказал (под-, как в «поднять»); атмерить → отмерить, атпилить → отпилить (от-, как в «отнять»); подерживал → поддерживал (под-держивать, две д: держал снизу, чтобы не упала); збегали → сбегали (с-); фсмотрелась → всмотрелась (в-смотреться); сдесь → здесь (приставки нет: зд — часть корня, слово запоминают).'},
 {n:7,l:1,st:4,task:'Сравнить почти-пары. Объяснить, чем различаются слова по значению и по составу. С каждым словом составить словосочетание.',
  obr:'Подделка — под-делка, фальшивка (подделка картины); поделка — по-делка, изделие своими руками (поделка из шишек).',
  body:'Подделка — поделка; поддержанный — подержанный; поддать — подать; ссыпать — сыпать; ввести — вести; оттирать — отирать.',
  key:'Подделка (фальшивка: подделка подписи) — поделка (изделие: поделка из глины). Поддержанный (кем-то поддержан: поддержанное классом предложение) — подержанный (бывший в употреблении: подержанный автомобиль). Поддать (под-дать, ударить снизу: поддать мяч коленом) — подать (по-дать: подать руку). Ссыпать (с-сыпать, собрать в одно место: ссыпать крупу в банку) — сыпать (сыпать песок). Ввести (в-вести, внутрь: ввести новое правило) — вести (вести урок). Оттирать (от-тереть, удалять трением: оттирать пятно) — отирать (о-тирать, вытирать: отирать пот со лба).'},
 {n:8,l:1,st:2,task:'Образовать от каждого слова два новых слова с приставками, данными в скобках. Записать их. Подчеркнуть приставки, в которых согласный звучит не так, как пишется.',
  obr:'Писать (под-, над-) — подписать, надписать (в обоих д звучит как [т]).',
  body:'Писать (под-, над-); бежать (от-, с-); катить (от-, с-); ставить (в-, пред-); шить (об-, с-); жечь (под-, с-); гореть (с-, от-); делать (с-, от-); ходить (в-, об-); сказать (пред-, под-); бить (от-, с-); давить (с-, от-).',
  key:'Подписать, надписать (т); отбежать (д), сбежать (з); откатить (т — звучит ясно), скатить (с — ясно); вставить (ф), представить (т); обшить (п), сшить (ш); поджечь (д — перед ж ясно), сжечь (ж); сгореть (з), отгореть (д); сделать (з), отделать (д); входить (ф), обходить (п); предсказать (т), подсказать (т); отбить (д), сбить (з); сдавить (з), отдавить (д).'},
 {n:9,l:1,st:3,task:'Списать, вставляя пропущенные буквы в приставках. Обозначить приставки. Объяснить, почему согласный приставки пишется не так, как слышится.',
  obr:'Пре..чувствие — предчувствие: приставка пред- пишется так же, как в «предложить».',
  body:'Предложения: 1) Но он не о..бежал ещё пятидесяти шагов, как вдруг остановился, словно вкопанный. (И. С. Тургенев, «Записки охотника») 2) Весь этот день Литвинов всё посмеивался, даже когда о..ходил своё хозяйство и о..давал приказания. (И. С. Тургенев, «Дым») 3) Не ..говариваясь, но, очевидно, по одному и тому же тайному побуждению, они нарочно ..делали значительный крюк, чтобы ещё раз пройти мимо «Дружбы». (А. И. Куприн, «Белый пудель») 4) Едва только Антон Прокофьевич появился в дверях, как в то же мгновение был о..ступлен всеми. (Н. В. Гоголь, «Повесть о том, как поссорился Иван Иванович с Иваном Никифоровичем») 5) Судьба вторично доставила мне случай по..слушать разговор, который должен был решить его участь. (М. Ю. Лермонтов, «Герой нашего времени») 6) Пугачёв несколько раз по..ступал под Оренбург со всеми своими силами. (А. С. Пушкин, «История Пугачёва»)',
  key:'1) Отбежал (от-). 2) Обходил (об-), отдавал (от-). 3) Сговариваясь (с-), сделали (с-). 4) Обступлен (об-). 5) Подслушать (под-). 6) Подступал (под-). Во всех словах приставка пишется так же, как там, где её согласный звучит ясно: от-нять, об-нять, с-нять, под-нять.'},
 {n:10,l:1,st:4,task:'Распределить слова по трём группам: 1) зд, зв, зр в начале — часть корня; 2) сд, сб, сг в начале — приставка с-; 3) приставка с- перед з, ж, ш. Обозначить приставку. Объяснить, как различить группы 1 и 2, если звучат они одинаково.',
  obr:'Здание — 1 (нечего отделить: «дание» — не слово). Сдача — 2 (с-дача, от «сдать»).',
  body:'Здание, сдача, сзади, здешний, сдержанный, сжатый, здравствуйте, сделка, сшитый, сгусток, здоровяк, сбоку, сжалиться, сдвинуть, звонарь, сгибать, сбежать, зрачок, сжечь, сдвоенный.',
  key:'1) Здание, здешний, здравствуйте, здоровяк, звонарь, зрачок. 2) С-дача, с-держанный, с-делка, с-густок, с-боку, с-двинуть, с-гибать, с-бежать, с-двоенный. 3) С-зади, с-жатый, с-шитый, с-жалиться, с-жечь.<br>Различаем так: в группе 2 после отделения с остаётся живая часть слова, родственная другим словам (держать, делать, бок, гнуть); зд как начало корня — только в словах «здание», «здесь», «здоровье» и родственных.'},
 {n:11,l:1,st:3,task:'Раскрыть скобки: написать слитно или раздельно. Объяснить: это приставка или отдельное короткое слово. Подсказка: в отдельное слово можно вставить ещё одно слово.',
  obr:'(На)писал (на)доске — написал (приставка), на доске (отдельное слово: на чёрной доске).',
  body:'Предложения: 1) Воробей (в)летел (в)открытую форточку. 2) Лыжник (с)бежал (с)горы и (за)смеялся. 3) Мы (под)бежали (под)навес, когда хлынул дождь. 4) Лодки (от)плыли (от)берега. 5) Художник (над)писал название (над)рисунком. 6) (До)дома мы (до)брались только к вечеру. 7) Кот (за)глянул (за)дверь. 8) Ребята (по)шли (по)узкой тропинке через сосновый бор, где пахло смолой и прогретой хвоей.',
  key:'1) Влетел (приставка), в открытую (отдельное слово). 2) Сбежал, с горы, засмеялся. 3) Подбежали, под навес. 4) Отплыли, от берега. 5) Надписал, над рисунком. 6) До дома, добрались. 7) Заглянул, за дверь. 8) Пошли, по узкой.'},
 {n:12,l:1,st:5,os:'диктант',task:'Записать текст под диктовку. Обозначить приставки, в которых согласный звучит не так, как пишется. Подчеркнуть слова, где зд — часть корня.',
  body:'Скворечник. В субботу мы с отцом сделали скворечник. Отец отпилил шесть дощечек, а я сбил их гвоздями. Сбоку мы сделали вход, а сверху приладили крышу. Вдвоём мы отнесли домик в сад и подвесили на старую яблоню. Здесь ему будет спокойно. Через неделю над садом раздался звонкий свист. Это вернулся из дальних краёв скворец! Он обошёл домик, отдохнул на ветке и подсел к входу. Видно, новое жилище пришлось ему по душе. Теперь каждое утро нас будит его песня. Как здорово, что мы не поленились!',
  key:'Согласный приставки звучит иначе: с-делали [з] (дважды), с-бил [з], с-боку [з], в-ход [ф] (вход, к входу), от-дохнул [д], под-сел [т]. Звучат ясно: от-пилил, в-двоём, от-несли, под-весили, обо-шёл, раз-дался. Зд в корне: здесь, здорово.'},
 {n:13,l:1,st:4,task:'Вставить пропущенные буквы. Объяснить, какое правило помогает в каждом случае: приставка пишется всегда одинаково; безударный гласный корня проверяется ударением; парный согласный корня проверяется словом, где после него гласный.',
  obr:'О..резать к..нец верёвки — отрезать (приставка от- не меняется), конец (ко́нчик).',
  body:'Предложения: 1) По..писать ч..тёж. 2) О..бежать от в..лны. 3) Пре..ставить новую ска..ку. 4) О..ход вокруг пру..а занял час. 5) ..ломанные ве..ки сложили в коро..ку. 6) Вдруг брат по..скочил и о..крыл окно, чтобы впустить св..жий воздух и послушать, как поют др..зды. 7) На..вигалась гр..за.',
  key:'1) Подписать (под-) чертёж (черта). 2) Отбежать (от-) от волны (волны́ — во́лны). 3) Представить (пред-) новую сказку (сказочный). 4) Обход (об-) вокруг пруда (пруды). 5) Сломанные (с-) ветки (веточка) в коробку (коробочка). 6) Подскочил (под-), открыл (от-), свежий (све́жесть), дрозды (дрозд). 7) Надвигалась (над-), гроза (гро́зы).'},
 {n:14,l:1,st:2,task:'Обозначить в словах приставку и корень (уголком и дугой). Подобрать к каждому слову однокоренное с другой приставкой.',
  obr:'Отправить: от- — приставка, прав — корень; другое слово — направить.',
  body:'Отправить, надпись, обложка, предгорье, сдача, вход, подснежник, отголосок, сбор, подсказка, оттенок, вставка, обрыв, предмостье, сжатие.',
  key:'От-прав-ить (направить); над-пис-ь (подпись); об-лож-ка (подложить); пред-горь-е (пригорок); с-да-ч-а (передача); в-ход (выход); под-снеж-ник (заснеженный); от-голос-ок (подголосок); с-бор (набор); под-сказ-ка (рассказ); от-тен-ок (затенить); в-став-ка (подставка); об-рыв (разрыв); пред-мост-ье (подмостки); с-жа-ти-е (нажатие).'},
// ── Урок 2. Приставки на з и с
 {n:15,l:2,st:1,task:'Выписать слова в два столбика: 1) приставка на з; 2) приставка на с. Подчеркнуть букву, которая идёт сразу после приставки, и надписать над ней: гл. (гласный), зв. (звонкий), глух. (глухой).',
  obr:'Безоблачный — 1 (после приставки гласный о). Бесконечный — 2 (глухой к).',
  body:'Безоблачный, бесконечный, разбить, расколоть, избежать, испечь, взлететь, вспыхнуть, возникнуть, воскликнуть, бездомный, бесшумный, распилить, изредка, исправить, разморозить, растаять, безлюдный, бесценный, взбежать, восторг, чересчур, чрезмерный, издать.',
  key:'1) Безоблачный (гл.), разбить (зв.), избежать (зв.), взлететь (зв.), возникнуть (зв.), бездомный (зв.), изредка (зв.), разморозить (зв.), безлюдный (зв.), взбежать (зв.), чрезмерный (зв.), издать (зв.).<br>2) Бесконечный, расколоть, испечь, вспыхнуть, воскликнуть, бесшумный, распилить, исправить, растаять, бесценный, восторг, чересчур — везде после приставки глухой согласный.'},
 {n:16,l:2,st:2,task:'Списать, вставляя з или с. Объяснить выбор буквы по следующему звуку.',
  obr:'Бе..донный колодец — бездонный: д — звонкий.',
  body:'Бе..донный колодец, ра..ступиться перед машиной, и..мерить рост, бе..хитростный рассказ, во..горелся спор, ра..чесать волосы, бе..граничная степь, в..пахать поле, бе..толковая суета, ра..винтить гайку, и..ломать карандаш, бе..характерный человек, во..хищённый взгляд, ра..дуть пламя, бе..форменная куча, в..бить подушку, ра..цвела сирень, бе..мятежный сон, и..тратить деньги, ра..мешать сахар, бе..чувственный человек, ни..ходить с горы, ра..шить ковёр узором, бе..вредный.',
  key:'Бездонный (д), расступиться (с), измерить (м), бесхитростный (х), возгорелся (г), расчесать (ч), безграничная (г), вспахать (п), бестолковая (т), развинтить (в), изломать (л), бесхарактерный (х), восхищённый (х), раздуть (д), бесформенная (ф), взбить (б), расцвела (ц), безмятежный (м), истратить (т), размешать (м), бесчувственный (ч), нисходить (х), расшить (ш), безвредный (в).'},
 {n:17,l:2,st:2,task:'1) Заменить сочетания одним словом с приставкой без- или бес-. Обозначить приставку. 2) Объяснить, почему отдельное слово «без» в первом столбике всегда пишется с з.',
  obr:'Без конца — бесконечный (перед глухим к — с).',
  body:'Без конца, без шума, без облаков, без дома, без сердца, без вкуса, без следа, без жалости, без страха, без толку, без пощады, без звука, без совести, без ветра, без цели, без помощи, без границ, без сил.',
  key:'1) Бесконечный, бесшумный, безоблачный, бездомный, бессердечный, безвкусный, бесследный, безжалостный, бесстрашный, бестолковый, беспощадный, беззвучный, бессовестный, безветренный, бесцельный, беспомощный, безграничный, бессильный.<br>2) Отдельное слово «без» не приставка: правило о з и с касается только приставок, а отдельное «без» пишется одинаково перед любым словом (без шума, без страха).'},
 {n:18,l:2,st:3,task:'Вставить одну или две буквы. Разделить слово на приставку и корень. Подчеркнуть слово с корнем чёт, где пишется одна с, и два слова, где приставки нет совсем.',
  obr:'Ра..казать — рас-сказать: корень на с, две с.',
  body:'Ра..казать, бе..ердечный, ра..чёт, ра..читать, бе..чётный, бе..аботный, ра..ердиться, и..ледовать, бе..мертный, во..тановить, ра..вет, ра..ыпать, бе..вучный, ра..орить, ра..адорить, ра..уждать, бе..ащитный, ра..ыграть, ра..инуть рот, и..ушить.',
  key:'Рас-сказать, бес-сердечный, рас-чёт (одна с: корень чёт), рас-считать, бес-счётный, без-заботный, рас-сердиться, ис-следовать, бес-смертный, вос-становить, рас-свет, рас-сыпать, без-звучный, разорить (приставки нет, одна з), раз-задорить, рас-суждать, без-защитный, раз-ыграть (одна з: корень на и), разинуть (приставки нет, одна з), ис-сушить.<br>Одна с при корне чёт: расчёт; без приставки: разорить, разинуть.'},
 {n:19,l:2,st:3,task:'1) Вставить а или о, поставить ударение. Записать слова парами. 2) Списать предложения, вставляя а или о.',
  obr:'Р..злить воду — разли́ть: ударение на корне, приставка без ударения — раз-.',
  body:'1) Р..зыгрыш — р..зыграть; р..спись — р..списание; р..зыск — р..зыскать; р..ссыпь — р..ссыпать; р..спуск — р..спустить; р..ссказни — р..ссказ. 2) Предложения: Учитель вывесил р..списание уроков. Мы долго любовались старинной р..списью на потолке храма. В траве блестела р..ссыпь ягод. На школьном празднике устроили р..зыгрыш призов. Птицы р..злетелись.',
  key:'1) Ро́зыгрыш — разыгра́ть; ро́спись — расписа́ние; ро́зыск — разыска́ть; ро́ссыпь — рассы́пать; ро́спуск — распусти́ть; ро́ссказни — расска́з.<br>2) Расписа́ние, ро́списью, ро́ссыпь, ро́зыгрыш, разлете́лись.'},
 {n:20,l:2,st:2,task:'Списать, вставляя з или с. Над вставленной буквой надписать, какой звук идёт после приставки (глух. или зв., гл.).',
  obr:'Бе..граничный — безграничный (г — зв.).',
  body:'Предложения: 1) «Однако надо же познакомиться, — думал я, бе..порядочно ра..хаживая по песчаной равнине, ра..стилавшейся перед Нескучным, — но как?» (И. С. Тургенев, «Первая любовь») 2) Видя моё бе..покойство, сообщившееся и моей сестрице, она уверила нас, что её и..пугал гром, что она боялась нашего и..пуга и что завтра будет здорова. (С. Т. Аксаков, «Детские годы Багрова-внука») 3) И всё для сердца и для глаз / Так было холодно-бе..цветно, / Так было грустно-бе..ответно, — / Но чья-то песнь вдруг ра..далась... (Ф. И. Тютчев, «Стихотворения») 4) Кругом бе..молвие; в глубоком смирении с неба смотрели звёзды, и шаги Старцева ра..давались так резко и некстати. (А. П. Чехов, «Ионыч»)',
  key:'1) Беспорядочно (п — глух.), расхаживая (х — глух.), расстилавшейся (с — глух., сс). 2) Беспокойство (п — глух.), испугал (п — глух.), испуга (п — глух.). 3) Бесцветно (ц — глух.), безответно (о — гл.), раздалась (д — зв.). 4) Безмолвие (м — зв.), раздавались (д — зв.).'},
 {n:21,l:2,st:3,task:'Списать, вставляя пропущенные буквы. Объяснить написание приставок. Найти в предложениях слова с приставками, которые не меняются, и обозначить их.',
  obr:'Бе..помощный — беспомощный: перед глухим п — с.',
  body:'Предложения: 1) Далеко на песок отодвинут / Трав морских бе..конечный и..вив, / Свод небесный, в воде опрокинут, / И..пещряет румянцем залив. (А. А. Фет, «Стихотворения») 2) Но вот он слышит короткое, бе..покойное, ласковое и призывающее ржание, которое так ему знакомо, что он всегда узнаёт его и..дали, среди тысяч других голосов. (А. И. Куприн, «Изумруд») 3) Она долго не могла поверить тому, чтобы ра..дор начался с такого бе..обидного, не близкого ничьему сердцу ра..говора. (Л. Н. Толстой, «Анна Каренина») 4) Десять лет прошло таким образом, бе..цветно, бе..плодно и быстро, страшно быстро. (И. С. Тургенев, «Отцы и дети»)',
  key:'1) Бесконечный (к — глух.), извив (в — зв.), испещряет (п — глух.); неизменяемая приставка: ото-двинут. 2) Беспокойное (п), издали (д); неизменяемые: у-знаёт (при-зывающее — урок 3). 3) Раздор (д), безобидного (о — гласный), разговора (г); неизменяемые: по-верить, на-чался. 4) Бесцветно (ц), бесплодно (п); неизменяемая: про-шло.'},
 {n:22,l:2,st:4,task:'Разграничить похожие случаи. Вставить пропущенные буквы, раскрыть скобки. Объяснить каждое написание.',
  obr:'Ра..считываться с продавцом — рассчитываться: рас- + считать, две с.',
  body:'Предложения: 1) Ра..чётливый хозяин заранее ра..читал все расходы. 2) В небе горели бе..чётные звёзды. 3) Буря ра..орила наш огород. 4) Щенок ра..орвал газету. 5) Малыш ра..инул рот от удивления. 6) Это было чере..чур смело. 7) Мы переправились (через) реку на пароме. 8) Случай был чре..вычайный. 9) Котёнок крался (без) шума, совершенно бе..шумно. 10) Дети остались (без) присмотра, но вели себя бе..упречно.',
  key:'1) Расчётливый (рас + чёт — одна с), рассчитал (рас + считать — две с). 2) Бессчётные (бес + счёт — две с). 3) Разорила (приставки нет, одна з). 4) Разорвал (раз-о-рвать: приставка разо-). 5) Разинул (приставки нет). 6) Чересчур (черес- перед глухим ч). 7) Через реку (отдельное слово, всегда з). 8) Чрезвычайный (чрез- перед звонким в). 9) Без шума (отдельное слово), бесшумно (бес- перед ш). 10) Без присмотра (отдельное слово), безупречно (без- перед гласным у).'},
 {n:23,l:2,st:4,task:'Найти в тексте ошибки в приставках на з и с (их девять) и исправить. Объяснить каждое исправление.',
  obr:'Безсильный → бессильный: перед глухим с — с, на стыке сс.',
  body:'Ночью в лесу. Мы шли безшумно, стараясь не разбудить птиц. Безконечный лес растилался до самого горизонта. Вдруг в кустах что-то зашуршало. Я разкрыл рот, чтобы вскрикнуть, но брат шепнул: «Не бойся, это ёжик!» Ёжик вылез на тропинку, бесстрашно оглядел нас и неторопливо расположился у пня. Мы расмеялись и сразу перестали безпокоиться. Ночь была безоблачной, и над нами разсыпались безчисленные звёзды. Мы уходили, расчитывая вернуться сюда утром, когда исчезнет туман.',
  key:'Безшумно → бесшумно (ш — глух.); безконечный → бесконечный (к); растилался → расстилался (рас + стилать, сс); разкрыл → раскрыл (к); расмеялись → рассмеялись (рас + смеяться, сс); безпокоиться → беспокоиться (п); разсыпались → рассыпались (с, сс); безчисленные → бесчисленные (ч); расчитывая → рассчитывая (рас + считать). Верно написаны: разбудить, вскрикнуть, бесстрашно, расположился, безоблачной, исчезнет.'},
 {n:24,l:2,st:3,task:'Заполнить таблицу своими примерами: для каждой приставки — по два слова перед звонким (или гласным) и по два перед глухим согласным. Обозначить приставки.',
  obr:'Без-/бес-: безоблачный, безводный — бесплатный, бесконечный.',
  body:'Приставки: без-/бес-, раз-/рас-, из-/ис-, воз-/вос-, вз-/вс-.',
  key:'Например: без-/бес-: безграничный, безоблачный — бескрайний, бесполезный; раз-/рас-: разбудить, разлить — растопить, расколоть; из-/ис-: избегать, изжарить — испугаться, исколоть; воз-/вос-: возглавить, возникнуть — воспитать, восход; вз-/вс-: взлететь, взбежать — вскипеть, вспахать. Проверить: после приставки на з — гласный или звонкий, на с — глухой.'},
 {n:25,l:2,st:5,task:'Сложный текст для разбора. Выписать все слова с приставками на з и с, обозначить приставку и объяснить букву. Отдельно выписать слова, в которых на стыке приставки и корня пишутся две одинаковые буквы. Найти слово, где две приставки подряд на з/с и на с-. Пояснения: биваки — стоянки под открытым небом.',
  obr:'Бездействию — без- перед звонким д.',
  body:'Предложения: 1) Хозяин залез в халат безвыходно, предавши тело бездействию, а мысль — обдумыванью большого сочиненья о России. (Н. В. Гоголь, «Мёртвые души») 2) Черпая ложкой уху, я беспрестанно заглядывался на оркестр музыкантов и беспрестанно обливался. (С. Т. Аксаков, «Детские годы Багрова-внука») 3) Всё минувшее, всё, что было заглушено нынешними казацкими биваками, суровой бранною жизнью, — всё всплыло разом на поверхность, потопивши, в свою очередь, настоящее. (Н. В. Гоголь, «Тарас Бульба») 4) Расстроенный, взволнованный Недопюскин не расслышал слов незнакомого ему господина, но прочие тотчас все замолкли; остряк снисходительно улыбнулся. (И. С. Тургенев, «Записки охотника»)',
  key:'Приставки на з/с: без-выходно (в — зв.), без-действию (д — зв.), бес-престанно (п — глух.), вс-плыло (п — глух.), рас-строенный (с — глух.), вз-волнованный (в — зв.), рас-слышал (с — глух.), с-нис-ходительно (нис- перед глухим х).<br>Две одинаковые буквы на стыке: расстроенный, расслышал.<br>Две приставки подряд: снисходительно (с- и нис-).<br>Неизменяемые приставки: об-думыванью, за-глядывался, об-ливался, за-глушено, по-топивши, за-молкли. «Предавши» (тело бездействию) — приставка пре- (предать = передать, подвергнуть), урок 4.'},
 {n:26,l:2,st:5,os:'диктант',task:'Записать текст под диктовку. Обозначить приставки на з и с, подчеркнуть букву после приставки. Отдельно выписать слова с двумя одинаковыми буквами на стыке.',
  body:'Перед грозой. С утра было безветренно и душно. Безоблачное небо раскалилось, и всё живое попряталось в тень. К полудню на западе вспыхнула молния, и вскоре раздался глухой раскат грома. Испуганные ласточки носились низко над рекой. Вдруг подул резкий ветер, растрепал листву, рассыпал по дороге сухие листья. Хлынул бесконечный ливень. Через час гроза рассеялась так же внезапно, как началась. Из-за туч показалось солнце, и мокрая трава засверкала бесчисленными искрами. Воздух стал чистым и свежим. Мы выбежали на крыльцо и долго не могли надышаться.',
  key:'Приставки на з/с: без-ветренно (в), без-облачное (о), рас-калилось (к), вс-пыхнула (п), раз-дался (д), рас-кат (к), ис-пуганные (п), рас-трепал (т), рас-сыпал (с), бес-конечный (к), рас-сеялась (с), бес-численными (ч). Две буквы на стыке: рассыпал, рассеялась. (Из-за — отдельное слово, не приставка.)'},
 {n:27,l:2,st:4,task:'Найти приставку, если она есть, и обозначить её. Объяснить, почему в некоторых словах нет приставки раз-/рас-, хотя слова начинаются с этих букв.',
  obr:'Рассвет — рас-свет (свет); растение — приставки нет (расти — корень раст).',
  body:'Растение, рассвет, расти, расчёска, низкий, низина, разум, разорвать, разорить, разуть, раздор, разевать, рассказ, разница, развалины, разведка, расход, раскраска.',
  key:'Без приставки: растение, расти (корень раст/рос), разум (корень разум), разорить и разевать (приставка сегодня не выделяется), разница (корень разн: разный), низкий и низина (корень низ, а не приставка низ-: «кий», «ина» — не слова).<br>С приставкой: рас-свет, рас-чёска (чесать), раз-о-рвать (разо-), раз-уть (обуть), раз-дор (драть), рас-сказ, раз-валины (валить), раз-ведка (ведать), рас-ход (ходить), рас-краска (краска).<br>Проверка: после отделения «раз/рас» должна остаться живая часть слова, родственная другим словам.'},
 {n:28,l:2,st:2,task:'От данных слов образовать новые с приставками в скобках. Записать, обозначить приставку, объяснить букву з или с.',
  obr:'Гнать (из-/ис-) — изгнать: г — звонкий.',
  body:'Гнать, пугать, жарить, черпать (из-/ис-); петь, хвалить, никнуть, родиться (воз-/вос-); бить, топить, резать, шить, будить, колоть (раз-/рас-); лететь, пахать, кипеть, бежать (вз-/вс-).',
  key:'Изгнать (г), испугать (п), изжарить (ж), исчерпать (ч); воспеть (п), восхвалить (х), возникнуть (н), возродиться (р); разбить (б), растопить (т), разрезать (р), расшить (ш), разбудить (б), расколоть (к); взлететь (л), вспахать (п), вскипеть (к), взбежать (б).'},
// ── Урок 3. Пре- и при-: значение приставки
 {n:29,l:3,st:1,task:'Распределить слова по значению приставки. Записать в таблицу из двух частей: пре- («очень»; близко к пере-) и при- (близость; приближение и присоединение; неполное действие; доведение до конца; в своих интересах).',
  obr:'Приморский — при-: близость (у моря). Преградить — пре-: близко к пере- (перегородить).',
  body:'Приморский, преградить, пребольшой, прибежать, приоткрыть, прервать, приручить, пришкольный, премилый, пришить, припрятать, преломить, присесть, прилететь, придумать, предобрый, приберечь, превратить, пригородный, приклеить.',
  key:'Пре- «очень»: пребольшой, премилый, предобрый. Пре- близко к пере-: преградить, прервать, преломить, превратить.<br>При- близость: приморский, пришкольный, пригородный. Приближение и присоединение: прибежать, пришить, прилететь, приклеить. Неполное действие: приоткрыть, присесть. Доведение до конца: приручить, придумать. В своих интересах: припрятать, приберечь.'},
 {n:30,l:3,st:2,task:'Списать, вставляя е или и. В скобках указать значение приставки.',
  obr:'Пр..бить полку — прибить (присоединение).',
  body:'Пр..плыть к берегу, пр..городный посёлок, пр..весёлая песня, пр..крыть калитку, пр..градить путь, пр..винтить полку, пр..мерзкая погода, пр..думать игру, пр..высить скорость, пр..усадебный участок, пр..стегнуть ремень, пр..образовать комнату, пр..берёг конфету для сестры, пр..скверное настроение, пр..вратиться в лёд, пр..тормозить у перехода, пр..увеличить свои успехи, пр..вязать бантик, пр..лечь отдохнуть, пр..умный кот, непр..рывный поток, беспр..станный шум.',
  key:'Приплыть (приближение), пригородный (близость), превесёлая (очень), прикрыть (неполное), преградить (пере-), привинтить (присоединение), премерзкая (очень), придумать (доведение до конца), превысить (сверх меры), приусадебный (близость), пристегнуть (присоединение), преобразовать (пере-), приберёг (в своих интересах), прескверное (очень), превратиться (пере-), притормозить (неполное), преувеличить (очень, сверх меры), привязать (присоединение), прилечь (неполное), преумный (очень), непрерывный (пере-: не прерывается), беспрестанный (пере-: не перестаёт).'},
 {n:31,l:3,st:2,task:'Заменить сочетания одним словом с приставкой пре- или при-. Объяснить значение приставки.',
  obr:'Очень добрый — предобрый (пре- = очень). Находящийся у моря — приморский (при- = близость).',
  body:'Очень добрый, находящийся у дороги, немного открыть, очень хорошенький, перегородить дорогу, сделать ручным, находящийся у вокзала, присоединить пуговицу нитками, сесть ненадолго, перервать, спрятать для себя, очень милый, расположенный у берега, немного поднять, очень неприятный, переломить (о лучах света в воде).',
  key:'Предобрый, придорожный, приоткрыть, прехорошенький, преградить, приручить, привокзальный, пришить, присесть, прервать, припрятать, премилый, прибрежный, приподнять, пренеприятный, преломить. Пре- — «очень» или близко к пере-; при- — близость, присоединение, неполное действие, доведение до конца, в своих интересах.'},
 {n:32,l:3,st:3,task:'Образовать слова с приставкой при- в указанном значении. Записать, рядом — исходное слово.',
  obr:'Близость: море — приморский.',
  body:'1) Близость: школа, город, берег, озеро, граница, вокзал. 2) Присоединение, прибавление: шить, клеить, крепить, строить, винтить, писать. 3) Неполное действие: открыть, поднять, глушить, тормозить, сесть, тихнуть. 4) Доведение до конца: ручной, учить, думать.',
  key:'1) Пришкольный, пригородный, прибрежный, приозёрный, приграничный, привокзальный. 2) Пришить, приклеить, прибавить, пристроить, привинтить, приписать. 3) Приоткрыть, приподнять, приглушить, притормозить, присесть, притихнуть. 4) Приручить, приучить, придумать.'},
 {n:33,l:3,st:3,task:'Списать, вставляя е или и. Объяснить значение приставки.',
  obr:'Пр..думать — придумать: довести мысль до результата (доведение до конца).',
  body:'Предложения: 1) Вдруг передо мною рытвина глубокая; скакун мой пр..задумался — и прыгнул. (М. Ю. Лермонтов, «Герой нашего времени») 2) Толстый сизый голубь пр..летел на дорогу и поспешно отправился пить в лужицу возле колодца. (И. С. Тургенев, «Отцы и дети») 3) Не сердись, голубчик, — кротко пр..рвала меня Олеся. (А. И. Куприн, «Олеся») 4) Эта речка вёрст за пять от Льгова пр..вращается в широкий пруд, по краям и кое-где посередине заросший густым тростником. (И. С. Тургенев, «Записки охотника») 5) Пр..миленький узор; так просто и благородно. (Л. Н. Толстой, «Анна Каренина») 6) Она пр..тихла, в свою очередь, и, не смигнув, наблюдала движение его мысли на лице. (И. А. Гончаров, «Обломов») 7) И опять она с ужасом чувствовала, что между ним и ею нет никакой пр..грады. (Л. Н. Толстой, «Война и мир»)',
  key:'1) Призадумался (неполное действие). 2) Прилетел (приближение). 3) Прервала (близко к пере-: перервала). 4) Превращается (близко к пере-: переходит в другое). 5) Премиленький (очень). 6) Притихла (неполное действие: немного стихла). 7) Преграды (близко к пере-: перегородка).'},
 {n:34,l:3,st:4,task:'Не путать пре- и пред-! Распределить слова по трём столбикам: 1) приставка пре-; 2) приставка при-; 3) приставка пред-. Обозначить приставку. Объяснить, как отличить пред- от пре-.',
  obr:'Предсказать — пред- (сказать заранее). Прервать — пре- (перервать).',
  body:'Предсказать, прервать, приехать, представить, преломить, предгорье, пригорок, превысить, предчувствие, приклеить, предутренний, преобразовать, придорожный, предложение, предгрозовой, прилечь, премудрый, предвидеть.',
  key:'1) Пре-: прервать, преломить, превысить, преобразовать, премудрый. 2) При-: приехать, пригорок, приклеить, придорожный, прилечь. 3) Пред-: пред-сказать, пред-ставить, пред-горье, пред-чувствие, пред-утренний, пред-ложение, пред-грозовой, пред-видеть.<br>Пред- значит «раньше, заранее» или «перед»: предгорье — перед горами, предвидеть — увидеть заранее. Проверка: если отбросить пред-, останется живая часть слова (сказать, ставить, горы, утро, гроза); д принадлежит приставке. У пре- после р сразу стоит е, а за ним корень: пре-рвать, пре-ломить.'},
 {n:35,l:3,st:3,task:'Составить словосочетания с данными словами. Объяснить значение приставки в каждом.',
  obr:'Приглушить — приглушить звук телевизора (неполное действие).',
  body:'Привинтить, приподнять, прикрепить, прибрежный, придумать, превозмочь, превзойти, пресытиться, превратить, приостановить, приучить, припрятать.',
  key:'Например: привинтить ручку (присоединение), приподнять крышку (неполное), прикрепить значок (присоединение), прибрежный песок (близость), придумать игру (доведение до конца), превозмочь страх (сверх меры: одолеть), превзойти ожидания (очень, сверх меры), пресытиться сладким (сверх меры), превратить воду в лёд (пере-), приостановить работу (неполное, на время), приучить к порядку (до результата), припрятать подарок (в своих интересах).'},
 {n:36,l:3,st:4,task:'Найти ошибки в написании пре- и при- (их восемь). Исправить, объяснить значение приставки.',
  obr:'Пристрашный → престрашный (очень страшный).',
  body:'Летом мы жили в приморском посёлке. Каждое утро я прибегал на берег и смотрел, как прилетают чайки. Однажды на прибрежный песок вынесло прибольшую корягу. Мы с другом решили прекрепить к ней парус и превратить её в корабль. Сначала мы её немного преподняли, потом преставили к ней палку и превязали к палке старую простыню. Ветер дул беспристанно, и простыня надулась. Корабль вышел присмешной! Даже соседский пёс перестал лаять и прелёг рядом, чтобы посмотреть на наше чудо.',
  key:'Прибольшую → пребольшую (очень); прекрепить → прикрепить (присоединение); преподняли → приподняли (немного); преставили → приставили (приближение, присоединение); превязали → привязали (присоединение); беспристанно → беспрестанно (не переставая); присмешной → пресмешной (очень); прелёг → прилёг (неполное действие: лёг ненадолго). Верно написаны: приморском, прибегал, прилетают, прибрежный, превратить (пере-), перестал.'},
 {n:37,l:3,st:5,task:'Сложный текст для разбора. Выписать слова с приставками пре- и при-, объяснить значение каждой. Найти слова, где рядом стоят две приставки, и слова с при-, значение которых угадывается с трудом. Пояснения: уязвить — задеть, обидеть.',
  obr:'Преувеличенно — пре-: сверх меры (слишком увеличенно).',
  body:'Предложения: 1) Этим да ещё преувеличенно приподнятою шляпой при поклоне он думал его уязвить. (И. С. Тургенев, «Дым») 2) Резко зачернелись они на внезапно вспыхнувшем пламени, затрещали, задымились и пошли коробиться, приподнимая обожжённые концы. (И. С. Тургенев, «Записки охотника») 3) Тогда старый Януш, бывший некогда одним из мелких графских служащих, выхлопотал себе нечто вроде звания управляющего и приступил к преобразованиям. (В. Г. Короленко, «Дети подземелья») 4) Временами он мог позабыть всё, принявшись за кисть, и отрывался от неё не иначе, как от прекрасного прерванного сна. (Н. В. Гоголь, «Портрет»)',
  key:'1) Преувеличенно (пре-: сверх меры), приподнятою (при-: немного подняли). 2) Приподнимая (при-: немного). 3) Приступил (при-: начал, приблизился к делу), преобразованиям (пре-: близко к пере-, перестройка). 4) Принявшись (при-: начав), прекрасного (пре-: очень красивого), прерванного (пре-: перерванного).<br>Две приставки подряд: при-под-нятою, при-под-нимая (при- и под-), пре-об-разованиям (пре- и об-). С трудом угадывается значение в словах «приступил» (к делу) и «принявшись» (за кисть): оба значат «начал», при- — «приблизиться к делу».'},
 {n:38,l:3,st:5,os:'сочинение',task:'Написать сочинение-миниатюру (6–8 предложений) «На берегу» или «Утро у реки». Употребить не меньше шести слов с приставкой при- разных значений и трёх слов с приставкой пре-. Обозначить приставки и надписать над ними значение.',
  body:'Опорные слова (можно брать и свои): прибрежный, прилететь, присесть, привстать, притихнуть, приплыть, прекрасный, премилый, преломиться, превратиться.',
  key:'Критерии: 6–8 предложений по теме; не меньше девяти слов с пре-/при-; значения подписаны верно (при-: близость — прибрежный, приближение — прилетели, неполное — присел, притихла; пре-: очень — прекрасный, премилый; пере- — прервала, превратился). Например: «Ранним утром я пришёл на прибрежный луг. К воде прилетели чайки, а я присел на камень и притих. Прекрасная тишина стояла над рекой. Вдруг её прервал всплеск: к берегу приплыла утка с утятами…»'},
 {n:39,l:3,st:3,task:'Сравнить слова в парах. Объяснить, как приставка меняет значение. Составить с одним словом из каждой пары предложение.',
  obr:'Перегородить — преградить: пре- близко к пере- (одно значение: поставить преграду).',
  body:'Перегородить — преградить; перервать — прервать; переломить — преломить; переступить — преступить (закон); перемудрить — премудрый; открыть — приоткрыть; сесть — присесть; бежать — прибежать.',
  key:'Первые четыре пары: пре- близко по значению к пере-. Перемудрить (слишком мудрить) — премудрый (пре-: очень мудрый). Приоткрыть, присесть — при-: неполное действие. Прибежать — при-: приближение. Предложения — свои, например: «Упавшее дерево преградило путь».'},
 {n:40,l:3,st:2,task:'Выписать слова в два столбика: 1) можно подставить «очень»; 2) можно подставить «пере-». Вставить пропущенные буквы.',
  obr:'Пр..добрый — предобрый (очень добрый): 1.',
  body:'Пр..весёлый, пр..рвать, пр..длинный, пр..градить, пр..интересный, пр..ломление, пр..смешной, пр..вращение, пр..глупый, пр..образование, пр..ступить закон, пр..хитрый.',
  key:'1) Превесёлый, предлинный, преинтересный, пресмешной, преглупый, прехитрый.<br>2) Прервать, преградить, преломление, превращение, преобразование, преступить.'},
 {n:41,l:3,st:4,task:'Лингвистическая задача. 1) Объяснить, почему часть слова называется «при-ставка». Какое значение приставки при- здесь «спрятано»? 2) Почему приставки пре- и пере- так похожи по значению? 3) Подобрать по три пары слов с пре- и пере- с близким значением.',
  obr:'При-ставка — то, что приставляют к корню: при- значит присоединение.',
  body:'Опорные слова: приставка, пристроить, приставить; преграда — перегородка; брег — берег; глава — голова.',
  key:'1) Приставка — то, что «приставлено» к корню; при- — присоединение. 2) Пре- — старославянская форма той же приставки, что русская пере- (как брег — берег, глава — голова), поэтому значения близки. 3) Например: преградить — перегородить, прервать — перервать, преломить — переломить (а также преступить — переступить).'},
 {n:42,l:3,st:4,task:'Вставить е или и. В каждом слове перед пре- или при- стоит ещё одна приставка или после неё идёт вторая. Мысленно убрать лишнюю приставку и определить значение пре- или при-.',
  obr:'Непр..вычный — непривычный: не- + при- (привыкнуть — доведение до конца).',
  body:'Непр..рывный дождь, беспр..станный стук, пр..остановить работу, пр..поднять тяжёлый ящик, пр..одеться к празднику, пр..украсить историю, непр..метный домик, пр..увеличенный восторг, пр..спущенный флаг, пр..обнять за плечи.',
  key:'Непрерывный, беспрестанный (бес- + пре-: перестать), приостановить (при- + о-: на время), приподнять (при- + под-: немного), приодеться (неполное: немного нарядиться), приукрасить (прибавить красоты), неприметный (не- + при-: такой, что его трудно приметить), преувеличенный (сверх меры), приспущенный (неполное: спущен не до конца), приобнять (неполное: слегка обнять).'},
// ── Урок 4. Пре- и при-: словарные слова и почти-пары
 {n:43,l:4,st:1,task:'Прочитать слова. Записать в два столбика: с пре- и с при-. Подчеркнуть в каждом слове пре- или при-. Выучить слова наизусть.',
  obr:'Преследовать — 1, привередливый — 2.',
  body:'Преследовать, привередливый, пренебречь, приключение, препятствие, прилежный, преподаватель, приличный, прелестный, присмиреть, прежний, прибор, пресмыкающиеся, приказ, преимущество, причудливый, пресловутый, приятный, знаки препинания, приют.',
  key:'С пре-: преследовать, пренебречь, препятствие, преподаватель, прелестный, прежний, пресмыкающиеся, преимущество, пресловутый, препинания.<br>С при-: привередливый, приключение, прилежный, приличный, присмиреть, прибор, приказ, причудливый, приятный, приют.'},
 {n:44,l:4,st:2,task:'Списать словосочетания, вставляя е или и. Проверить себя по словарю.',
  obr:'Пр..ятная новость — приятная (словарное слово).',
  body:'Пр..следовать цель, пр..небрежительный тон, непр..ступная крепость, пр..вередливый покупатель, неожиданное пр..ключение, пр..лежная ученица, пр..подавать историю, пр..личное поведение, пр..лестная улыбка, пр..смиревший щенок, пр..жний адрес, измерительный пр..бор, строгий пр..каз, пр..имущество команды, пр..чудливый узор, пр..скорбный случай, непр..тязательный вкус, беспр..кословно подчиниться, пр..ятный голос, пр..вольные луга.',
  key:'Преследовать, пренебрежительный, неприступная (при-: к ней нельзя приступить, подойти), привередливый, приключение, прилежная, преподавать, приличное, прелестная, присмиревший, прежний, прибор, приказ, преимущество, причудливый, прискорбный, непритязательный, беспрекословно, приятный, привольные.'},
 {n:45,l:4,st:2,task:'Вставить е или и в словах из других языков. Объяснить значение слов (можно по словарю). Составить словосочетания с пятью из них.',
  obr:'Пр..зентация — презентация (представление): презентация книги.',
  body:'Пр..мьера, пр..зидент, пр..вилегия, пр..парат, пр..оритет, пр..стиж, пр..митивный, пр..тензия, пр..ватный, пр..людия, пр..тендент, пр..зидиум, пр..мия, пр..цедент, пр..мадонна.',
  key:'Премьера, президент, привилегия (особое право), препарат, приоритет (первенство), престиж (уважение, авторитет), примитивный (простейший), претензия, приватный (частный), прелюдия (музыкальное вступление), претендент, президиум, премия, прецедент (случай-образец), примадонна. С при-: привилегия, приоритет, примитивный, приватный, примадонна; остальные — с пре-.'},
 {n:46,l:4,st:3,task:'Вставить е или и, объяснить выбор по смыслу (записать в скобках синоним).',
  obr:'Делегация пр..бывает в Москву — прибывает (приезжает).',
  body:'Предложения: 1) Завтра утром в Москву пр..бывает делегация из Китая. 2) Всё лето, пока мы пр..бывали в лагере на берегу Волги, дома шли дожди. 3) После дождей вода пр..бывает. 4) Розовый оттенок облакам пр..дало заходящее солнце. 5) Нельзя пр..давать друзей! 6) Своему пр..емнику старый мастер передал и инструменты, и секреты ремесла, которые знал только он. 7) Дедушка долго настраивал радиопр..ёмник. 8) Ветер пр..творил окно. 9) Свой давний замысел строители наконец пр..творили в жизнь. 10) У памятника героям войны путники молча пр..клонили головы. 11) Тяжёлые от плодов ветки яблони садовник осторожно пр..клонил к земле. 12) К экзамену ученики пр..ступили ровно в девять.',
  key:'1) Прибывает (приезжает). 2) Пребывали (находились). 3) Прибывает (прибавляется). 4) Придало (прибавило). 5) Предавать (изменять). 6) Преемнику (продолжателю). 7) Радиоприёмник (прибор). 8) Притворил (прикрыл). 9) Претворили (осуществили). 10) Преклонили (склонили в знак почтения). 11) Приклонил (пригнул). 12) Приступили (начали).'},
 {n:47,l:4,st:3,task:'Составить с каждым словом пары предложение. Записать предложения, подчеркнуть слово-двойник, в скобках указать его значение.',
  obr:'Пребывать — Бабушка пребывает в санатории (находится).',
  body:'Пребывать — прибывать; предать — придать; преемник — приёмник; претворить — притворить; преступить — приступить; предел — придел; преходящий — приходящий; претерпеть — притерпеться.',
  key:'Например: Гости прибывают к обеду (приезжают). Друг не предаст (не изменит). Мастер придал вазе форму (дал, прибавил). Преемник продолжил дело учителя. Приёмник ловит радиоволны. Мечту претворили в жизнь (осуществили). Притворите дверь (прикройте). Нельзя преступать закон (нарушать). Приступим к уроку (начнём). Есть предел терпению (граница). В храме есть придел (пристройка). Это преходящие трудности (временные). К нам ходит приходящая няня. Путешественники претерпели лишения (перенесли). Мы притерпелись к шуму (привыкли).'},
 {n:48,l:4,st:3,task:'Списать, вставляя пропущенные буквы. Объяснить написание пре- и при-: значение или словарное слово.',
  obr:'Пр..вередливо — привередливо: словарное слово.',
  body:'Предложения: 1) Харин, пр..следовавший его целые тридцать вёрст, пр..нуждён был остановиться. (А. С. Пушкин, «История Пугачёва») 2) Это пр..ключение, уверял он, напоминало ему пр..жнее время и гусарские проказы. (А. С. Пушкин, «Повести Белкина») 3) Французы пр..писывали пожар ему, и впоследствии, во время пр..бывания его во Франции, после Реставрации, это считалось славным актом патриотизма. (Л. Н. Толстой, «Война и мир») 4) Императрица и великие княжны, блистая красотою и нарядами, прохаживались между рядами гостей, пр..ветливо с ними разговаривая. (А. С. Пушкин, «Арап Петра Великого») 5) Это было признаком, что я не боюсь противника и даже отчасти намекаю на моё к нему пр..зрение. (В. Г. Короленко, «Дети подземелья»)',
  key:'1) Преследовавший (словарное), принуждён (словарное). 2) Приключение (словарное), прежнее (словарное). 3) Приписывали (при-: присоединение, приписать кому-то), пребывания (пребывать — находиться). 4) Приветливо (словарное). 5) Презрение (словарное: презирать).'},
 {n:49,l:4,st:4,task:'Разграничить почти-пары. Выбрать нужное слово из скобок, объяснить выбор. В двух предложениях подходит только одно слово, хотя оба кажутся возможными, — найти их и доказать.',
  obr:'Котёнок (пребывал, прибывал) в отличном настроении — пребывал (находился).',
  body:'Предложения: 1) Каждый год в апреле с юга (пребывают, прибывают) скворцы. 2) Полгода на орбите космонавты (пребывают, прибывают) в невесомости. 3) Нельзя (предать, придать) огласке чужую тайну. 4) (Предала, придала) лицу мягкость улыбка. 5) Перед уходом на пенсию тренер воспитал себе достойного (преемника, приёмника), которому доверил свою команду. 6) Сломался (преемник, приёмник). 7) Решения собрания надо (претворить, притворить) в жизнь как можно скорее. 8) Мальчик (претворился, притворился) спящим, хотя слышал каждое слово. 9) Перед памятником павшим отец (преклонил, приклонил) голову. 10) Своим силам он не знал (предела, придела).',
  key:'1) Прибывают (прилетают). 2) Пребывают (находятся в невесомости). 3) Предать огласке (сделать известным — устойчивое сочетание с пре-). 4) Придала (прибавила). 5) Преемника (продолжателя). 6) Приёмник (прибор). 7) Претворить (осуществить). 8) Притворился (сделал вид). 9) Преклонил (в знак уважения). 10) Предела (границы).<br>Кажутся возможными оба: 3 (предать огласке — не «изменить», а «передать», поэтому пре-) и 9 (приклонить можно ветку, но голову в знак почтения — преклонить).'},
 {n:50,l:4,st:4,task:'Найти ошибки в написании пре- и при- (их пять). Исправить и объяснить. Помнить о почти-парах: проверять смысл каждого слова-двойника.',
  obr:'Принебрегали → пренебрегали (словарное слово).',
  body:'Наш класс собирался в поход. Нас пригласил учитель географии, наш любимый приподаватель. Сначала нас приследовали неудачи: автобус опаздывал, и группа прибыла на станцию только к обеду. Но мы не пали духом. Пребыв на место, мы разбили лагерь у прелестного озера. Самым привередливым оказался Петя: ему всё было не так. Зато Маша вела себя прилично и прилежно помогала дежурным. Вечером мы слушали радиопреёмник и рассказывали истории о приключениях. Учитель сказал, что наш поход претворил в жизнь его давнюю мечту, и это нас очень обрадовало. Ночью над лагерем шумел ветер, но к утру он притих. Ни одно препятствие не помешало нам, а беспрекословная дисциплина и дружба сделали поход незабываемым. Только Петя притворялся, будто ему скучно, хотя все видели, что он доволен. Мы притерпели много трудностей, но не жалеем ни о чём.',
  key:'Приподаватель → преподаватель (словарное); приследовали → преследовали (словарное); пребыв → прибыв (прибыть — приехать); радиопреёмник → радиоприёмник (прибор); притерпели → претерпели (перенесли). Это пять исправлений; верно написаны: пригласил, прибыла, прелестного, привередливым, прилично, прилежно, приключениях, претворил (осуществил), притих, препятствие, беспрекословная, притворялся (делал вид).'},
 {n:51,l:4,st:2,task:'Подобрать к словам синонимы-толкования. Записать парами. Вставить пропущенные буквы.',
  obr:'Пр..бывать (в отпуске) — пребывать: находиться.',
  body:'Пр..бывать (в отпуске), пр..бывать (о поезде), пр..дать (друга), пр..дать (форму), пр..ступить (закон), пр..ступить (к работе), пр..творить (дверь), пр..творить (план), пр..емник (дела), пр..ёмник (радио), пр..дел (мечтаний), пр..терпеться (к холоду), пр..вратник (у ворот), пр..вратность (судьбы).',
  key:'Пребывать — находиться; прибывать — приезжать; предать — изменить; придать — прибавить; преступить — нарушить; приступить — начать; притворить — прикрыть; претворить — осуществить; преемник — продолжатель; приёмник — прибор; предел — граница; притерпеться — привыкнуть; привратник — сторож у ворот (при-: близость); превратность — изменчивость, неожиданный поворот (пре-: превратить).'},
 {n:52,l:4,st:3,task:'Распределить слова по трём группам: 1) значение пре- или при- видно (указать какое); 2) словарное слово; 3) слово из другого языка. Вставить пропущенные буквы.',
  obr:'Пр..вокзальный — привокзальный: 1, близость.',
  body:'Пр..вокзальный, пр..следовать, пр..мьера, пр..милый, пр..вередливый, пр..клеить, пр..оритет, пр..градить, пр..лежный, пр..зидент, пр..встать, пр..пятствие, пр..вилегия, пр..ломить, пр..личный, пр..стиж, пр..ручить, пр..небрегать.',
  key:'1) Привокзальный (близость), премилый (очень), приклеить (присоединение), преградить (пере-), привстать (неполное), преломить (пере-), приручить (до конца). 2) Преследовать, привередливый, прилежный, препятствие, приличный, пренебрегать. 3) Премьера, приоритет, президент, привилегия, престиж.'},
 {n:53,l:4,st:5,task:'Сложный текст для разбора. Вставить пропущенные буквы. Для каждого слова с пре- или при- определить: значение приставки, словарное слово или почти-пара (указать вторую). Найти слово с приставкой пред-, которое легко спутать с пре-. Пояснения: уравновешенность — спокойствие.',
  obr:'Пр..дал (огласке) — предал (сделал известным, «передал»; пара — придал).',
  body:'Моему деду в молодости пришлось долго пр..бывать на далёкой северной станции. Каждую весну туда пр..бывал корабль с почтой и продуктами. Дед говорил, что жизнь там пр..подала ему главный урок: в трудный час не пр..давай товарищей и не пр..давай значения мелочам. Пр..пятствий было много: пурга пр..граждала дорогу, мороз пр..вращал воду в лёд. Но полярники пр..терпели всё и не потеряли уравновешенности. Начальника станции дед считал своим учителем, а потом стал его пр..емником. Пр..следуя одну цель — изучить ледник, — они пр..творили в жизнь смелый замысел. Дед до сих пор хранит старый радиопр..ёмник, который принимал тогда сигналы с Большой земли, и с гордостью пр..дставляет его гостям.',
  key:'Пребывать (находиться; пара — прибывать), прибывал (приезжал; пара — пребывал), преподала (словарное: преподавать), не предавай (не изменяй; пара — придавай), не придавай значения (не прибавляй; пара — предавай), препятствий (словарное), преграждала (пере-: перегораживала), превращал (пере-), претерпели (перенесли; пара — притерпелись), преемником (продолжателем; пара — приёмник), преследуя (словарное), претворили (осуществили; пара — притворили), радиоприёмник (прибор; пара — преемник), представляет — приставка пред- (пред-ставлять: ставить перед), её не путать с пре-.'},
 {n:54,l:4,st:5,os:'диктант',task:'Записать текст под диктовку. Подчеркнуть слова с пре- и при-, над ними надписать: значение, «словарное» или «пара».',
  body:'Прибытие. Поезд прибывал на станцию рано утром. Мы приникли к окну. За стеклом проплывали пригородные посёлки, низенькие домики, придорожные берёзы. Прекрасное утро превращало всё вокруг в праздник. Наконец поезд притормозил и остановился. На перроне нас встречал дедушка. Он приветливо помахал рукой и прижал нас к себе. Пока мы пребывали у него в гостях, нас ждало немало приключений. Дедушка преподавал когда-то в школе и знал о здешних местах всё. Он показал нам старинную церковь с приделом и родник, у которого путники преклоняли колени. Каникулы пролетели незаметно, и мы с грустью уезжали, пообещав непременно вернуться.',
  key:'Прибывал (пара: пребывать; приезжал), приникли (приближение), пригородные (близость), придорожные (близость), прекрасное (очень), превращало (пере-), притормозил (неполное), приветливо (словарное), прижал (присоединение, сверху вниз), пребывали (пара: прибывать; находились), приключений (словарное), преподавал (словарное), приделом (пара: предел; пристройка храма), преклоняли (пара: приклонять; в знак почтения), непременно (словарное).'},
 {n:55,l:4,st:4,task:'Выполнить задание в формате ЕГЭ. Указать варианты ответов, в которых во всех словах одного ряда пропущена одна и та же буква. Записать номера ответов. Вставить буквы, объяснить.',
  obr:'Ряд «пр..вязать, пр..городный, пр..слониться» — везде и (присоединение, близость, приближение).',
  body:'Ряды: 1) пр..бывать в гостях, пр..небречь, пр..рвать;<br>2) пр..ступить к делу, пр..морский, пр..одолеть;<br>3) пр..дать форму, пр..лежный, пр..чудливый;<br>4) пр..творить мечту, пр..следовать, пр..смыкаться;<br>5) пр..ехать, пр..рода, пр..мьера.',
  key:'Ответ: 1, 3, 4.<br>1) Пребывать (находиться), пренебречь, прервать — е. 2) Приступить (начать, и), приморский (и), преодолеть (е) — разные. 3) Придать (прибавить), прилежный, причудливый — и. 4) Претворить (осуществить), преследовать, пресмыкаться — е. 5) Приехать (и), природа (и), премьера (е) — разные.'},
 {n:56,l:4,st:3,task:'Составить мини-словарик трудных слов урока: выписать десять слов с пре- и при-, к каждому — толкование (своими словами или по словарю) и словосочетание.',
  obr:'Пренебречь — не обратить внимания, отнестись свысока: пренебречь опасностью.',
  body:'Слова на выбор: пренебречь, преследовать, препятствие, прелестный, приветливый, привередливый, приключение, прилежный, присмиреть, непритязательный, беспрекословный, непреклонный, приоритет, привилегия.',
  key:'Например: преследовать — гнаться (преследовать зверя); препятствие — помеха (преодолеть препятствие); прелестный — очаровательный (прелестный вечер); приветливый — дружелюбный (приветливая улыбка); привередливый — капризный в выборе (привередливый едок); приключение — неожиданное событие (морские приключения); прилежный — старательный (прилежный ученик); присмиреть — стать тихим (котёнок присмирел); непритязательный — нетребовательный (непритязательное растение); беспрекословный — без возражений (беспрекословное послушание); непреклонный — твёрдый (непреклонная воля); приоритет — первенство (приоритет безопасности); привилегия — особое право (привилегия победителя).'},
// ── Урок 5. Ы и и после приставок
 {n:57,l:5,st:1,task:'Образовать новые слова, присоединив приставки. Записать в два столбика: 1) после приставки пишется ы; 2) пишется и. Обозначить приставку.',
  obr:'С- + играть — сыграть (1). Вы- + играть — выиграть (2).',
  body:'Играть (с-, вы-, раз-, про-, об-, до-, под-, за-); искать (от-, по-, раз-, под-, об-); история (пред-, до-).',
  key:'1) Сыграть, разыграть, обыграть, подыграть; отыскать, разыскать, подыскать, обыскать; предыстория.<br>2) Выиграть, проиграть, доиграть, заиграть; поискать; доисторический.<br>После приставки на согласный — ы, после приставки на гласный — и.'},
 {n:58,l:5,st:2,task:'Списать, вставляя ы или и. Обозначить приставку, подчеркнуть её последнюю букву.',
  obr:'Без..сходный — безысходный: без- кончается на согласный.',
  body:'Об..скать все углы, под..тожить результаты года, без..мянная высота, без..нтересная книга, пред..дущая глава, с..грать на скрипке, от..граться в следующем матче, роз..грыш кубка, по..грать в мяч, вы..грать забег, без..дейный фильм, об..грать соперника, при..скать слово, до..сторические времена, без..нициативный работник, из..скать средства, на..гранная улыбка, раз..граться не на шутку.',
  key:'Обыскать, подытожить, безымянная, безынтересная, предыдущая, сыграть, отыграться, розыгрыш, поиграть, выиграть, безыдейный, обыграть, приискать, доисторические, безынициативный, изыскать, наигранная, разыграться. И — после по-, вы-, при-, до-, на- (на гласный).'},
 {n:59,l:5,st:3,task:'Вставить ы или и. Распределить слова по группам: 1) ы по правилу; 2) и после приставки на гласный; 3) и после меж- и сверх-; 4) и после иноязычной приставки; 5) исключение. Объяснить каждую группу.',
  obr:'Сверх..нтересный — 3: после сверх- пишется и.',
  body:'Сверх..нтересный, меж..нститутский, вз..мать, вз..скать, контр..гра, без..сходный, по..скать, пост..ндустриальный, меж..гровой, под..грать, вы..скать время, супер..гра, сверх..зысканный, пред..стория, за..грать, суб..нспектор.',
  key:'1) Взыскать, безысходный, подыграть, предыстория. 2) Поискать, выискать, заиграть. 3) Сверхинтересный, межинститутский, межигровой, сверхизысканный. 4) Контригра, постиндустриальный, суперигра, субинспектор. 5) Взимать.<br>После ж и х ы не пишется; иноязычные приставки не меняют и; взимать — исключение.'},
 {n:60,l:5,st:3,task:'Списать, вставляя пропущенные буквы. Объяснить написание ы и и после приставок. Обозначить все приставки.',
  obr:'Из..скать — изыскать: из- на согласный, и → ы.',
  body:'Предложения: 1) Быстрые взоры царя от..скали в толпе молодую хозяйскую дочь; он подозвал её. (А. С. Пушкин, «Арап Петра Великого») 2) Сражение вы..грает тот, кто твёрдо решил его вы..грать. (Л. Н. Толстой, «Война и мир») 3) Он иногда боязливо косится на тёмный угол, ожидая, что воображение с..грает с ним штуку и покажет сверхъестественное явление. (И. А. Гончаров, «Обломов») 4) Дай тебе про себя я с..граю / Под басовую эту струну. (С. А. Есенин, «Стихотворения») 5) Он выждал первый перерыв разговора и с расстроенным лицом вышел из комнаты от..скивать Соню. (Л. Н. Толстой, «Война и мир»)',
  key:'1) Отыскали (от- + искать), подозвал (подо-). 2) Выиграет, выиграть (вы- на гласный — и). 3) Сыграет (с- + играть — ы). В слове «сверхъестественное» после сверх- пишется ъ, а не ы и не и: корень начинается с е (правило — в главе «Ъ и Ь»). 4) Сыграю (с-). 5) Отыскивать (от-); перерыв (пере-), разговора (раз-), расстроенным (рас- + строить, сс).'},
 {n:61,l:5,st:4,task:'Найти и исправить ошибки (их семь). Объяснить каждое исправление.',
  obr:'Безинтересный → безынтересный: без- на согласный, и → ы.',
  body:'В субботу наша команда должна была сиграть с соседней школой. Перед матчем тренер подитожил наши прошлые игры и разобрал предидущий матч, в котором мы проиграли. «Надо обиграть их в середине поля», — сказал он. Мы долго розыскивали запасной мяч и наконец отыскали его под скамейкой. Игра вышла сверхынтересной. Мы выграли со счётом три — два! Вечером в школе устроили розыгрыш призов, а судья пообещал взыскать штраф с тех, кто опоздает на следующую игру.',
  key:'Сиграть → сыграть; подитожил → подытожил; предидущий → предыдущий; обиграть → обыграть; розыскивали → разыскивали (без ударения раз-; в «ро́зыск» под ударением роз-); сверхынтересной → сверхинтересной (после сверх- — и); выграли → выиграли (вы- + играть, и). Верно: проиграли, отыскали, розыгрыш, взыскать.'},
 {n:62,l:5,st:2,task:'От данных слов образовать новые с указанными приставками. Записать, обозначить приставку, объяснить букву после неё.',
  obr:'Искать (вз-) — взыскать: вз- на согласный, ы.',
  body:'Искать (вз-, раз-, по-); играть (об-, вы-, раз-); итог (под-); имя (без-); идейный (без-); интересный (без-, сверх-); исторический (до-); институтский (меж-); инициативный (без-).',
  key:'Взыскать, разыскать, поискать (и); обыграть, выиграть (и), разыграть; подытожить; безымянный; безыдейный; безынтересный, сверхинтересный (и); доисторический (и); межинститутский (и); безынициативный. После русских приставок на согласный — ы; после приставок на гласный и после меж-, сверх- — и.'},
 {n:63,l:5,st:5,task:'Сложное задание: в каждом слове действует не одно правило главы. Вставить пропущенные буквы и объяснить все написания.',
  obr:'Бе..скусный — безыскусный: без- перед гласным — з; после приставки на согласный и → ы.',
  body:'Ра..скать, бе..нтересный, бе..мянный, во..меть влияние, р..зыгрыш, р..зыграть, в..скать долг, в..мать плату, небе..звестный, бе..сходный, сверх..зысканный, по..тожить, ро..ск, бе..нициативный, бе..дейный, пре..стория.',
  key:'Разыскать (раз- перед гласным; ы), безынтересный (без- перед гласным; ы), безымянный (без-; ы), возыметь (воз-; ы), ро́зыгрыш (под ударением роз-; ы), разыгра́ть (без ударения раз-; ы), взыскать (вз-; ы), взимать (вз-; исключение — и), небезызвестный (не- + без-; ы), безысходный (без-; ы), сверхизысканный (после сверх- — и; дальше из- перед гласным — з, ы: из + искать), подытожить (под- не меняется; ы), ро́зыск (роз- под ударением; ы), безынициативный (без-; ы), безыдейный (без-; ы), предыстория (пред- не меняется; ы).'},
 {n:64,l:5,st:5,os:'диктант',task:'Записать текст под диктовку. Обозначить приставки; подчеркнуть ы и и после приставок, объяснить их.',
  body:'Розыгрыш. В нашем дворе каждую весну проходит розыгрыш кубка по футболу. В прошлом году мы проиграли в финале, а в этот раз решили отыграться. Целый месяц мы тренировались и подыскивали новых игроков. Перед игрой капитан подытожил всё, что мы узнали о соперниках, и рассказал, как их обыграть. Матч получился сверхинтересным. Мы долго не могли забить, но в конце игры Саша неожиданно разыграл комбинацию и забил гол. Мы выиграли! Кубок мы поставили в школьном музее рядом с безымянным портретом, который когда-то нашли в архиве.',
  key:'Ро́зыгрыш (роз-, ы), проиграли (про-, и), отыграться (от-, ы), подыскивали (под-, ы), подытожил (под-, ы), обыграть (об-, ы), сверхинтересным (сверх-, и), разыграл (раз-, ы), выиграли (вы-, и), безымянной (без-, ы), разыскали (раз-, ы). Остальные приставки: про-, от-, под-, об-, раз-, вы-, без- и др.'},
 {n:65,l:5,st:3,task:'Заполнить таблицу: в левой колонке — приставки, в правой — по два слова с корнем на и после этой приставки. Указать букву. Приставки: с-, от-, под-, раз-, без-, вы-, по-, меж-, сверх-.',
  obr:'С-: сыграть, сызнова — ы.',
  body:'Приставки: с-, от-, под-, раз-, без-, вы-, по-, меж-, сверх-.',
  key:'Например: с- — сыграть, сымпровизировать (ы); от- — отыскать, отыграться (ы); под- — подытожить, подыграть (ы); раз- — разыскать, разыграть (ы); без- — безымянный, безынтересный (ы); вы- — выиграть, выискать (и); по- — поиграть, поискать (и); меж- — межинститутский, межигровой (и); сверх- — сверхинтересный, сверхизысканный (и).'},
 {n:66,l:5,st:4,task:'Сравнить пары слов. Объяснить, почему в одинаковом корне пишутся разные буквы. Составить с одним словом каждой пары словосочетание.',
  obr:'Сыграть — выиграть: после с- (согласный) — ы, после вы- (гласный) — и.',
  body:'Сыграть — выиграть; разыскать — поискать; взыскать — взимать; безынтересный — сверхинтересный; предыстория — доисторический; подыграть — контригра; изымать — взимать.',
  key:'Сыграть (с- на согласный: ы) — выиграть (вы- на гласный: и). Разыскать (раз-: ы) — поискать (по-: и). Взыскать (по правилу ы) — взимать (исключение: и). Безынтересный (без-: ы) — сверхинтересный (после х ы не пишут: и). Предыстория (пред-: ы) — доисторический (до-: и). Подыграть (русская под-: ы) — контригра (иноязычная контр-: и). Изымать (из-: ы) — взимать (исключение: и, хотя корень тот же).'},
 {n:67,l:5,st:3,task:'Списать предложения, вставляя пропущенные буквы. Объяснить написание. Найти предложения, где после приставки пишется и.',
  obr:'Раз..граться не на шутку — разыграться (раз- на согласный).',
  body:'Предложения: 1) Метель, которая раз..гралась ночью, к утру замела все дороги в посёлке. 2) Тропинку мы долго в..искивали среди сугробов. 3) Под..грывать младшему брату в шахматах мама не любит. 4) Учёные изучают пред..сторию города. 5) После уроков ребята по..грали в снежки, пока не стемнело, и, усталые, разошлись по домам. 6) Нужное слово подруга всегда умеет под..скать. 7) Так закончилась пред..дущая глава. 8) На олимпиаде было много меж..нститутских команд, и все они боролись за победу до последней минуты.',
  key:'1) Разыгралась (раз-: ы). 2) Выискивали (вы- на гласный: и). 3) Подыгрывать (под-: ы). 4) Предысторию (пред-: ы). 5) Поиграли (по- на гласный: и). 6) Подыскать (под-: ы). 7) Предыдущая (пред-: ы). 8) Межинститутских (после меж- — и). И — в предложениях 2, 5, 8.'},
 {n:68,l:5,st:2,task:'Выписать из текста все слова, в которых корень начинается с и (ы) после приставки. Обозначить приставку, объяснить букву.',
  obr:'Отыскал — от-: на согласный, ы.',
  body:'Дедушка отыскал на чердаке старый альбом. В нём были фотографии доисторических ракушек, которые он когда-то разыскивал на берегу. Мы долго рассматривали снимки и пытались подыскать название каждой находке. Потом дедушка сыграл нам на гармошке, а мы поиграли в лото. Вечер получился совсем не безынтересным!',
  key:'Отыскал (от-, ы), доисторических (до-, и), разыскивал (раз-, ы), подыскать (под-, ы), сыграл (с-, ы), поиграли (по-, и), безынтересным (без-, ы).'},
 {n:69,l:5,st:4,task:'Лингвистическая задача. 1) Почему в словах «сыграть» и «отыскать» буква в корне меняется вслед за произношением, а в слове «подписать» согласный приставки не меняется, хотя звучит иначе? 2) Почему после сверх- пишется и, а после из- — ы, хотя обе приставки кончаются на согласный? 3) Что общего у слов «взимать» и «изымать»?',
  obr:'1) В словах «сыграть», «отыскать» твёрдый согласный приставки меняет звук [и] на [ы] — это отражается на письме по особому правилу.',
  body:'Опорные слова: сыграть, отыскать, подписать, сверхинтересный, изыскать, взимать, изымать.',
  key:'1) Правило о ы после приставок — особое: после твёрдого согласного приставки [и] звучит как [ы], и письмо это отражает. Согласные приставок (кроме з/с) пишутся единообразно, их оглушение не отражается. 2) После х (и ж в меж-) буква ы в русском письме не пишется, поэтому сверхинтересный; после из- — по общему правилу ы: изыскать. 3) У них один старый корень «имать» (брать); изымать пишется по правилу (ы), а взимать — исключение (и), потому что так и произносится.'},
 {n:70,l:5,st:2,task:'Составить и записать восемь словосочетаний со словами урока: по два слова с ы и по два с и после приставки, по одному слову с меж- и сверх-, одно — взимать, одно — с иноязычной приставкой.',
  obr:'Отыскать потерянный ключ (ы); выиграть первый приз (и).',
  body:'Слова для выбора: выискать, разыграть, предыстория, подытожить, безымянный, выиграть, поискать, доисторический, межинститутский, сверхинтересный, изымать, контригра.',
  key:'Например: разыграть сценку, подытожить работу (ы); поискать грибы, доисторический ящер (и); межинститутская конференция (меж-); сверхинтересная экскурсия (сверх-); изымать находку (из-: ы); опасная контригра соперника (иноязычная контр-). Проверить букву после приставки по правилу урока.'},
// ── Повторение
 {n:71,l:6,st:3,task:'Распределительный диктант. Записать слова в пять столбиков по правилам главы: 1) неизменяемая приставка; 2) приставка на з/с; 3) пре-; 4) при-; 5) ы после приставки. Вставить пропущенные буквы.',
  obr:'По..пилить — 1 (подпилить). Бе..шумный — 2 (бесшумный).',
  body:'По..пилить, бе..крайний, пр..ломить, пр..вязать, от..граться, ..делать, ра..колоть, пр..вередливый, раз..граться, о..бросить, и..пугаться, пр..мудрый, пр..ручить, без..мянный, на..пись, во..главить, пр..следовать, пр..тормозить, пред..дущий, ..горать.',
  key:'1) Подпилить, сделать, отбросить, надпись, сгорать. 2) Бескрайний, расколоть, испугаться, возглавить. 3) Преломить, премудрый, преследовать. 4) Привязать, привередливый, приручить, притормозить. 5) Отыграться, разыграться, безымянный, предыдущий (в «разыграться» и «безымянный» работают ещё и правила о з/с).'},
 {n:72,l:6,st:4,task:'Выполнить задание в формате ЕГЭ. Указать варианты ответов, в которых во всех словах одного ряда пропущена одна и та же буква. Записать номера ответов. Вставить буквы, объяснить.',
  obr:'Ряд «бе..жалостный, ра..дать, во..никнуть» — везде з (после приставки звонкий согласный).',
  body:'Ряды: 1) бе..шумный, ра..колоть, и..портить;<br>2) с..грать, под..скать, без..дейный;<br>3) ра..бить, бе..вкусный, во..гордиться;<br>4) пр..рвать, пр..небречь, пр..вередливый;<br>5) ..делать, ..дание, ..бить.',
  key:'Ответ: 1, 2, 3.<br>1) Бесшумный, расколоть, испортить — с. 2) Сыграть, подыскать, безыдейный — ы. 3) Разбить, безвкусный, возгордиться — з. 4) Прервать (е), пренебречь (е), привередливый (и) — разные. 5) Сделать (с), здание (з), сбить (с) — разные.'},
 {n:73,l:6,st:4,task:'Выполнить задание в формате ЕГЭ. Указать варианты ответов, в которых во всех словах одного ряда пропущена одна и та же буква. Записать номера ответов. Вставить буквы, объяснить.',
  obr:'Ряд «пр..клеить, пр..брежный, пр..тихнуть» — везде и (присоединение, близость, неполное действие).',
  body:'Ряды: 1) пр..ехать, пр..школьный, пр..липнуть;<br>2) пр..сечь слухи, пр..емник учителя, пр..увеличить;<br>3) раз..грать, меж..гровой, без..нтересный;<br>4) ра..цвести, и..чезнуть, бе..хитростный;<br>5) р..списание, р..зыгрыш, р..зыскать.',
  key:'Ответ: 1, 2, 4.<br>1) Приехать, пришкольный, прилипнуть — и. 2) Пресечь (пере-: прекратить), преемник, преувеличить — е. 3) Разыграть (ы), межигровой (и), безынтересный (ы) — разные. 4) Расцвести, исчезнуть, бесхитростный — с. 5) Расписание (а), ро́зыгрыш (о), разыскать (а) — разные.'},
 {n:74,l:6,st:4,task:'Отредактировать текст: найти и исправить ошибки в приставках (их десять), объяснить каждое исправление. Озаглавить текст.',
  obr:'Безсонный → бессонный: перед глухим с — с, на стыке сс.',
  body:'Мы немного безпокоились, когда отправлялись в поход на лодках. Утро было прекрасным и безоблачным. Сначала мы проплыли мимо преморской деревни, потом росположились на обед у прибрежных ив. Пока мы отдыхали, ветер усилился и по реке побежали волны. Пришлось потождать, пока он стихнет. Брат потшутил над моим страхом, но я не обиделся. Потом мы нашли удобную бухту и устроили лагерь. Вечером дежурные пребыли из соседнего лагеря и предложили нам сиграть в волейбол. Наша команда выграла! Ночь была бесзвёздной, и над рекой расстилался туман. Мы долго сидели у костра и вспоминали самые интересные приключения дня. Утром нас ждала обратная дорога, но мы были бесконечно счастливы и уже расчитывали силы на обратный путь.',
  key:'Безпокоились → беспокоились (п); преморской → приморской (близость); росположились → расположились (без ударения рас-); потождать → подождать (подо-: приставка не меняется); потшутил → подшутил (под-); пребыли → прибыли (приехали); сиграть → сыграть (ы); выграла → выиграла (вы- + играть); бесзвёздной → беззвёздной (без- + звезда, зз); расчитывали → рассчитывали (рас- + считать). Заголовок, например: «Поход на лодках».'},
 {n:75,l:6,st:5,task:'Сложный текст для разбора. Выписать все слова с приставками, обозначить приставки и объяснить их написание по правилам главы. Отдельно выписать слова, в которых две приставки. Пояснения: отчёт — объяснение, ответ себе.',
  obr:'Изредка — из- перед звонким р.',
  body:'Предложения: 1) Изредка она останавливалась и, плача, приподнимая то одну озябшую лапу, то другую, старалась дать себе отчёт: как это могло случиться, что она заблудилась? (А. П. Чехов, «Каштанка») 2) Совладавши с равновесием и укрепившись на новой позиции, он изгибается и, стараясь не набрать в рот воды, начинает правой рукой шарить между корягами. (А. П. Чехов, «Налим») 3) На рассвете он завтра промчится, / Шапку-месяц пригнув под кустом, / И игриво взмахнёт кобылица / Над равниною красным хвостом. (С. А. Есенин, «Стихотворения»)',
  key:'1) Из-редка (из- перед звонким р), о-станавливалась (о-), при-под-нимая (при-: немного; две приставки), о-зябшую (о-), от-чёт (от-), с-лучиться (с-), за-блудилась (за-). 2) Со-владавши (со-), у-крепившись (у-), из-гибается (из- перед звонким г), на-брать (на-), на-чинает (на-). 3) Рас-свете (рас- перед с: две с), про-мчится (про-), при-гнув (при-: приближение к земле), вз-махнёт (вз- перед звонким м). Две приставки: приподнимая (при- + под-).'},
 {n:76,l:6,st:5,os:'диктант',task:'Записать текст под диктовку. Обозначить все приставки и объяснить их написание. Подчеркнуть слова с ы после приставки.',
  body:'Весенний лес. Ранним утром мы отправились в лес. Снег уже растаял, и по оврагам бежали беспокойные ручьи. Прозрачный воздух был прекрасен. Солнце приподнялось над вершинами елей и рассыпало по поляне золотые блики. Мы прислушались: где-то неподалёку отрывисто стучал дятел. Подснежники пробились сквозь прошлогоднюю листву. На опушке мы разыскали старый муравейник и долго наблюдали за его беспрестанной работой. Вдруг из кустов выскочил заяц. Он присел, приподнял уши и стремглав исчез в чаще. Мы с братом рассмеялись: заяц словно сыграл с нами шутку. Домой мы вернулись к обеду, пообещав себе прийти сюда снова.',
  key:'От-правились, рас-таял, бес-покойные, про-зрачный, пре-красен (очень), при-под-нялось (немного), рас-сыпало (сс), при-слушались, не-по-далёку, от-рывисто, под-снежники, про-бились, про-шлогоднюю, раз-ыскали (ы), бес-пре-станной (бес- + пре-), вы-скочил, при-сел, при-под-нял, ис-чез (ч — глух.), рас-смеялись (сс), с-ыграл (ы), вернулись — приставки нет, по-обещав, при-йти.'},
 {n:77,l:6,st:5,os:'сочинение',task:'Написать сочинение-миниатюру (7–9 предложений) «Как я заблудился (заблудилась)» или «Неожиданная встреча». Употребить слова на все правила главы: по два слова с неизменяемыми приставками, с приставками на з/с, с пре-, с при-, с ы после приставки. Обозначить приставки.',
  body:'Опорные слова: подбежать, сделать, бесстрашно, рассыпать, прекрасный, преодолеть, присесть, приблизиться, изыскать, подыграть.',
  key:'Критерии: 7–9 предложений по теме; не меньше десяти слов на пять правил главы, все приставки обозначены верно (под-, с- не меняются; бес- перед глухим, раз-/рас- по следующему звуку; пре- — очень или пере-; при- — приближение, неполное действие; ы после приставки на согласный). Например: «Я бесшумно приоткрыл калитку и вышел в прекрасный осенний сад…»'},
 {n:78,l:6,st:3,task:'Повторение по спирали. Вставить пропущенные буквы. Определить, где орфограмма в приставке, а где в корне. Объяснить каждую: правило приставки или проверка корня (ударением, чередованием).',
  obr:'Пр..л..теть — прилететь: при- (приближение); в корне е — проверка «лёт».',
  body:'Пр..л..теть к гнезду, ра..к..чать качели, бе..гр..мотное письмо, о..в..зти бабушку, по..р..сти за лето, на..к..сить яблоко, пр..м..рский город, ..г..рать на солнце, раз..гр..ть сценку, и..м..рить рост, пр..гр..дить путь, бе..д..рожье, бе..з..щитный птенец.',
  key:'Прилететь (при-: приближение; е — лёт), раскачать (рас- перед к; а — ка́чка), безграмотное (без- перед г; а — гра́мота), отвезти (от- не меняется; е — вёз), подрасти (под-; а — чередование раст перед ст), надкусить (над-; у — уку́с), приморский (при-: близость; о — мо́ре), сгорать (с-; о — чередование гар/гор: без ударения гор), разыграть (раз-, ы после приставки; а — игра́), измерить (из- перед м; е — ме́ра), преградить (пре- = пере-; а — огра́да), бездорожье (без-; о — доро́га), беззащитный (без- + за-: зз; а в приставке за- не меняется).'},
 {n:79,l:2,st:3,task:'Списать, вставляя пропущенные буквы. Объяснить написание приставок на з и с. В каждом предложении найти ещё одну приставку и сказать, по какому правилу она пишется.',
  obr:'Бе..полезно — бесполезно: перед глухим п — с.',
  body:'Предложения: 1) Клочков ра..терялся, ра..краснелся и от и..бытка чувств заходил вокруг стола. (А. П. Чехов, «Водевиль») 2) Когда ночная роса и горный ветер освежили мою горячую голову и мысли пришли в обычный порядок, то я понял, что гнаться за погибшим счастьем бе..полезно и бе..рассудно. (М. Ю. Лермонтов, «Герой нашего времени») 3) Изумруд, семимесячный стригунок, носится бе..цельно по полю, нагнув вниз голову и в..брыкивая задними ногами. (А. И. Куприн, «Изумруд») 4) Дорога шла между ра..бросанными группами дубов и орешника, покрывавшими луг. (Н. В. Гоголь, «Вий») 5) Вот оно бледнеет; синеет небо; отдельные тени и..чезают, воздух наливается мглою. (И. С. Тургенев, «Записки охотника») Пояснения: стригунок — жеребёнок до двух лет.',
  key:'1) Растерялся (т — глух.), раскраснелся (к — глух.), избытка (б — зв.); за-ходил — приставка за- не меняется. 2) Бесполезно (п), безрассудно (р — зв.); о-свежили, при-шли (при-: приближение), по-гибшим. 3) Бесцельно (ц), взбрыкивая (б — зв.); на-гнув. 4) Разбросанными (б); по-крывавшими. 5) Исчезают (ч — глух.); от-дельные (от- не меняется), на-ливается.'},
 {n:80,l:6,st:3,task:'Списать, вставляя пропущенные буквы. Над каждой приставкой надписать номер правила: 1 — приставка не меняется; 2 — приставка на з/с; 3 — пре-/при-; 4 — ы после приставки.',
  obr:'Пр..думала — придумала (3: доведение до конца).',
  body:'Предложения: 1) Вот как я пр..восходно пр..думала! — думала она про себя. (В. М. Гаршин, «Лягушка-путешественница») 2) Пр..задумался честной купец крепче прежнего. (С. Т. Аксаков, «Аленький цветочек») 3) Капитан Тушин, ра..порядившись по роте, послал одного из солдат от..скивать перевязочный пункт или лекаря для юнкера и сел у огня, ра..ложенного на дороге солдатами. (Л. Н. Толстой, «Война и мир») 4) Когда надоело дразнить меня солдатством, да я и пр..вык к тому и не так уже ра..дражался, от..скали другую, не менее чувствительную во мне струну. (С. Т. Аксаков, «Детские годы Багрова-внука») 5) Он ра..крыл занавески, и долго его и..пуганные, ра..бегавшиеся глаза не могли от..скать ребёнка. (Л. Н. Толстой, «Война и мир») Пояснения: честной — здесь: почтенный; юнкер — молодой военный.',
  key:'1) Превосходно (3: сверх меры, очень хорошо), придумала (3: до результата). 2) Призадумался (3: неполное, немного задумался). 3) Распорядившись (2: п — глух.), отыскивать (4), разложенного (2: л — зв.); по-слал (1). 4) Привык (3: доведение до конца), раздражался (2: д — зв.), отыскали (4). 5) Раскрыл (2: к), испуганные (2: п), разбегавшиеся (2: б), отыскать (4).'},
 {n:81,l:6,st:4,task:'В каждом ряду найти лишнее слово — то, что пишется по другому правилу или с другой буквой. Вставить буквы, объяснить.',
  obr:'Бе..вкусный, ра..бить, во..главить, и..портить — лишнее «испортить»: с перед глухим п, в остальных з.',
  body:'Ряды: 1) бе..платный, ра..колоть, и..редка, во..ход;<br>2) пр..морский, пр..тихнуть, пр..ломить, пр..шить;<br>3) от..грать, по..грать, вз..скать, под..тожить;<br>4) о..дать, по..писать, ..делать, ..дание;<br>5) пр..следовать, пр..небречь, пр..вередливый, пр..пятствие;<br>6) ра..чёт, ра..казать, бе..мертный, ра..ыпать.',
  key:'1) Изредка (з; остальные: бесплатный, расколоть, восход — с). 2) Преломить (е; остальные при-: приморский, притихнуть, пришить). 3) Поиграть (и после гласной приставки; остальные ы: отыграть, взыскать, подытожить). 4) Здание (корень, з; остальные — приставки: отдать, подписать, сделать). 5) Привередливый (и; остальные с е). 6) Расчёт (одна с; рассказать, бессмертный, рассыпать — сс).'},
 {n:82,l:6,st:5,task:'Тонкость. Мини-исследование: объяснить, почему эти слова пишутся «не по правилу» или кажутся исключениями. При необходимости воспользоваться теорией (блоки «Тонкости») и словарём.',
  obr:'Здесь — зд в корне: когда-то здесь была приставка, но звонкое произношение закрепилось, и слово перестало делиться.',
  body:'Слова: здесь, здоровье, разорить, разинуть, расчёт, бессчётный, небезызвестный, сверхинтересный, контригра, прелестный, преемник.',
  key:'Здесь, здоровье — зд стало частью корня (старая приставка с-). Разорить, разинуть — приставка не выделяется, одна з. Расчёт — рас- + чёт (одна с); бессчётный — бес- + счёт (две с). Небезызвестный — не- + без- + известный: после без- и → ы, хотя слово длинное и «составное». Сверхинтересный — после х ы не пишется. Контригра — иноязычная приставка не меняет и. Прелестный — пре- уже не выделяется (от «лесть»), слово словарное. Преемник — пре- близко к пере- (перенимать), не путать с «приёмник».'},
 {n:83,l:6,st:3,task:'По памяти составить схему-алгоритм «Как писать приставку» (вопрос — ответ — следующий вопрос). Проверить его на словах. Сравнить свою схему со схемой в уроке 5.',
  obr:'Шаг 1: Какая приставка? Если на з/с — смотрим следующий звук…',
  body:'Слова для проверки: по..бежать, бе..страшный, пр..градить, пр..дорожный, с..грать, ..дача, р..зыск, пр..вередливый, вз..мать, меж..здательский.',
  key:'Схема: 1) найти приставку; 2) на з/с? → глухой после неё — с, иначе з; под ударением роз-/рос-; 3) пре-/при-? → по значению; нет значения — словарь; пара — по смыслу; 4) другая приставка — не меняется; 5) корень на и после согласного — ы (кроме меж-, сверх-, взимать, иноязычных). Проверка: подбежать (под-), бесстрашный (сс), преградить (пере-), придорожный (близость), сыграть (ы), сдача (с-), ро́зыск (роз-, ы), привередливый (словарное), взимать (исключение), межиздательский (меж- — и).'},
 {n:84,l:6,st:5,task:'Сложный текст для разбора. Выписать слова с пре- и при-, объяснить написание. Найти слова с приставками на з/с и неизменяемыми приставками. Ответить: почему «презрительное» и «пресыщенное» пишутся с пре-, хотя значение у них разное?',
  obr:'Притворно — при- (притвориться — сделать вид; пара — претворить).',
  body:'Предложения: 1) Я, признаюсь, с негодованьем рассматривал его красное лицо, на котором сквозь притворно презрительное равнодушие проглядывало удовлетворённое, пресыщенное самолюбие. 2) Ну, это вы преувеличиваете, позвольте вам заметить, — прервал я его. 3) Я высунул голову из тарантаса, притаил дыхание — и действительно услыхал где-то далеко-далеко за нами слабый прерывистый стук, как бы от катившихся колёс. 4) Вы принимаете её за близкий лес; вы подходите — лес превращается в высокую грядку полыни на меже. (И. С. Тургенев, «Записки охотника») Пояснения: негодованье — возмущение; тарантас — дорожная повозка; межа — граница между полями.',
  key:'При- и пре-: признаюсь (при-: словарное), притворно (притвориться — сделать вид; пара — претворить), презрительное (словарное: презирать), пресыщенное (пре-: сверх меры, «слишком сытый»). Приставки на з/с: рас-сматривал (сс). Неизменяемые: про-глядывал, у-довлетворённое (у-), само- — часть сложного слова. 2) Преувеличиваете (пре-: сверх меры), прервал (пре- = пере-); по-звольте, за-метить. 3) Притаил (при-: неполное — ненадолго затаил), прерывистый (пре-: прерываться); вы-сунул, у-слыхал. 4) Принимаете (при-: словарное — принять), превращается (пре- = пере-: переходит в другое); под-ходите (под-: звучит [т]), на меже. Ответ на вопрос: в «презрительное» пре- не выделяется, слово запоминают; в «пресыщенное» видно значение высокой степени.' },
 {n:85,l:2,st:3,task:'Списать, вставляя пропущенные буквы в приставках на з и с. Объяснить написание. Найти в каждом предложении слово с неизменяемой приставкой.',
  obr:'Ра..глядеть — разглядеть: г — звонкий.',
  body:'Предложения: 1) Отец с во..хищением ра..сказывал мне, что видел лебедей, так высоко летевших, что он едва мог ра..глядеть их, и что гуси потянулись большими станицами. (С. Т. Аксаков, «Детские годы Багрова-внука») 2) Мы утешались в нашем бе..действии мыслию о скором прекращении скучной и мелочной войны с разбойниками и дикарями. (А. С. Пушкин, «Капитанская дочка») 3) И всё таинственней, бе..мерней / Их тень растёт, растёт, как сон; / Как тонко по заре вечерней / Их лёгкий очерк во..несён! (А. А. Фет, «Стихотворения») 4) Мальчик бегал взад и вперёд по той стороне ручья, пронзительно свистал и кричал громко, с бе..покойством и и..пугом: — Арто, иси! (А. И. Куприн, «Белый пудель») Пояснения: станица — здесь: стая птиц.',
  key:'1) Восхищением (х — глух.), рассказывал (с — глух., сс), разглядеть (г — зв.); по-тянулись. 2) Бездействии (д — зв.); неизменяемая: у-тешались. 3) Безмерней (м — зв.), вознесён (н — зв.); неизменяемая: о-черк (чертить). 4) Беспокойством (п — глух.), испугом (п — глух.); неизменяемая: в-перёд.'},
 {n:86,l:3,st:3,task:'Списать, вставляя е или и. Определить значение приставки при- в каждом слове.',
  obr:'Пр..сел — присел: сел ненадолго (неполное действие).',
  body:'Предложения: 1) Проходя мимо них, бабы и девки пр..останавливались и опускали головы. (Л. Н. Толстой, «Казаки») 2) Каленик пр..поднялся немного, но неодолимая сила пр..ковала его к скамейке. (Н. В. Гоголь, «Вечера на хуторе близ Диканьки») 3) Да признаться, — пр..бавил он после небольшого молчанья, — мне не на кого пенять, сам виноват. (И. С. Тургенев, «Записки охотника») 4) Наташа, красная, оживлённая, увидав мать на молитве, вдруг остановилась на своём бегу, пр..села и невольно высунула язык, грозясь самой себе. (Л. Н. Толстой, «Война и мир»)',
  key:'1) Приостанавливались (неполное: ненадолго останавливались). 2) Приподнялся (неполное: немного), приковала (присоединение). 3) Прибавил (прибавление); «признаться» — словарное. 4) Присела (неполное: ненадолго села).'},
 {n:87,l:5,st:3,task:'Списать, вставляя пропущенные буквы. Объяснить написание ы или и после приставок. Обозначить приставки.',
  obr:'Под..скать — подыскать: под- на согласный, и → ы.',
  body:'Предложения: 1) Буря ль раз..грается — / Старые кораблики / Приподымут крылышки, / По морю размечутся. (М. Ю. Лермонтов, «Герой нашего времени») 2) Переход через Березину, действительно, не сопровождался тяжёлыми боями, какие были в пред..дущих сражениях. (Л. Н. Толстой, «Война и мир») 3) Поэтому он не настаивал больше ни на дальнейших роз..сках Арто, ни на мировом, ни на других решительных мерах. (А. И. Куприн, «Белый пудель») 4) И так разгулялся, что, лихо под..грывая, сделал молодецкую выходку и пошёл один плясать по комнате. (Л. Н. Толстой, «Казаки») Пояснения: мировое — здесь: мирное соглашение.',
  key:'1) Разыграется (раз- на согласный: ы); при-под-ымут, раз-мечутся. 2) Предыдущих (пред-: ы); пере-ход, со-провождался. 3) Розысках (роз- под ударением, ы); на-стаивал. 4) Подыгрывая (под-: ы); раз-гулялся, с-делал, вы-ходку, по-шёл.'}
];
const PS_LNAMES=['',...PS.lessons.map(l=>l.t),'Повторение'];
const PS_BOOKREF={1:'Адамчик, «Правописание конечных согласных приставок»; Розенталь, § 18, п. 3',2:'Розенталь, «Русский язык» (пособие), § 18, упр. 80–86',3:'Розенталь, § 19, упр. 87–88; Сидорова, тема 6',4:'Розенталь, § 19, упр. 89–90; Адамчик, «Различайте приставки по значению слов»',5:'Розенталь, § 20, упр. 91; Сидорова, тема 4'};
